const litState={fragments:68,classics:72,lyric:58,translation:46,seed:0};
const litWords=['FRAGMENT','VOICE','GLOSS','ESSAY','MYTH','IMAGE','PAUSE','MEMORY','MARGIN','ECHO','FORM','TIME','BODY','CHORUS','NOTE','QUESTION'];
function litMetrics(){const values=[litState.classics,litState.lyric,litState.translation,100-litState.fragments*.25],mean=values.reduce((a,b)=>a+b,0)/values.length,variance=values.reduce((s,v)=>s+(v-mean)**2,0)/values.length,tension=DemoKit.clamp(Math.sqrt(variance)*1.7+litState.fragments*.48,0,100),count=4+Math.round(litState.fragments/7);let form='Hybrid';if(litState.fragments>78)form='Fragment';else if(litState.lyric>78)form='Lyric';else if(litState.classics>78&&litState.translation>60)form='Translation';return{tension,count,form}}
function updateLit(){const m=litMetrics();DemoKit.metric('formOutput',m.form);DemoKit.metric('fragmentOutput',m.count);DemoKit.metric('tensionOutput',`${Math.round(m.tension)}%`)}
const litController=DemoKit.animator(document.getElementById('literatureCanvas'),(ctx,w,h,t)=>{DemoKit.clear(ctx,w,h);const m=litMetrics(),cols=w<540?2:3,rows=Math.ceil(m.count/cols),cellW=w/(cols+1),cellH=h/(rows+1);for(let i=0;i<m.count;i++){const col=i%cols,row=Math.floor(i/cols),x=cellW*(col+1),y=cellH*(row+1),drift=Math.sin(t*.35+i*1.7+litState.seed)*8*(litState.fragments/100),type=i%3,color=type===0?'#ff8b72':type===1?'#75a9ff':'#f5d36b',width=DemoKit.clamp(72+litState.translation*.55+(i%4)*17,78,190),height=32+(i%3)*13;ctx.save();ctx.translate(x+drift,y+Math.cos(t*.28+i)*5);ctx.rotate(((i%5)-2)*.018*litState.fragments/10);ctx.fillStyle=color+'22';ctx.strokeStyle=color+'99';ctx.lineWidth=1.5;ctx.fillRect(-width/2,-height/2,width,height);ctx.strokeRect(-width/2,-height/2,width,height);ctx.fillStyle='#eef5ff';ctx.font=`${10+litState.lyric/35}px Georgia,serif`;ctx.textAlign='center';ctx.fillText(litWords[(i+litState.seed)%litWords.length],0,4);ctx.restore()}ctx.fillStyle='#9eacc0';ctx.font='11px ui-monospace,monospace';ctx.textAlign='left';ctx.fillText(`${m.form.toUpperCase()} · ${m.count} UNITS · TENSION ${Math.round(m.tension)}%`,18,h-22);updateLit()});
DemoKit.range('fragments','fragmentsValue',v=>`${v}%`,v=>litState.fragments=v);DemoKit.range('classics','classicsValue',v=>`${v}%`,v=>litState.classics=v);DemoKit.range('lyric','lyricValue',v=>`${v}%`,v=>litState.lyric=v);DemoKit.range('translation','translationValue',v=>`${v}%`,v=>litState.translation=v);DemoKit.wireButton(litController);document.getElementById('resetDemo').addEventListener('click',()=>{litState.seed=(litState.seed+3)%litWords.length;litController.reset()});updateLit();
